import {lazy, type RefObject, Suspense, useCallback, useRef, useState} from 'react'
import {Button} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {AgentIcon} from '@primer/octicons-react'
import {AlertMetadata, AlertMetadataContent, AlertMetadataHeader} from '@github-ui/platform-patterns/AlertPageSidebar'
import {useUpdateAlertAssigneesMutation} from '../hooks/use-update-alert-assignees-mutation'
import type {Assignee, UpdateAlertAssigneesResponse} from '../types'
import {AssigneePicker} from './AssigneePicker'
import {AssigneesList} from './AssigneesList'
import {displayFlashMessage} from '../flash-message'

const LazyCopilotAssignmentModal = lazy(async () => {
  const m = await import('@github-ui/agent-sessions/components/copilot-assignment/CopilotAssignmentModal')
  return {default: m.CopilotAssignmentModal}
})

const LazyCopilotAssignmentButton = lazy(async () => {
  const m = await import('@github-ui/agent-sessions/components/copilot-assignment/CopilotAssignmentButton')
  return {default: m.CopilotAssignmentButton}
})

export type CopilotAssignmentModalOnSubmit = (
  graphQLId: string,
  selectedBranch?: string,
  content?: string,
  selectedAgent?: {topLevelAgentId?: string; subAgentSlug?: string},
  selectedModel?: string,
  selectedRepoNwo?: string,
  selectedRepoId?: number,
) => void

export type CopilotAssignmentModalConfig = {
  repository: {name: string; owner: {login: string}}
  alertNumbers: number[]
  onAssignmentComplete?: () => void
  onSubmit?: CopilotAssignmentModalOnSubmit
  title?: string
  description?: string
}

export type AssigneesSectionProps<Response extends UpdateAlertAssigneesResponse = UpdateAlertAssigneesResponse> = {
  availableAssigneesPath: string
  updateAssigneesPath: string
  currentUser: Assignee
  assignees: Assignee[]
  readonly: boolean
  maxAssignees?: number
  onAssignmentChange?: () => void
  onCopilotAgenticAssignment?: (data: Response | null) => void
  assignableToCopilot?: boolean
  copilotAssignmentModal?: CopilotAssignmentModalConfig
  useAgenticAutofix?: boolean
  showAssignToAgentButton?: boolean
  assignToAgentAssignee?: Assignee | null
  onAssignError?: (error: Error) => void
}

const defaultOnAssignError = () => {
  displayFlashMessage('Unable to save your selection due to server error. Try again later.', 'error')
}

export function AssigneesSection<Response extends UpdateAlertAssigneesResponse = UpdateAlertAssigneesResponse>({
  availableAssigneesPath,
  updateAssigneesPath,
  currentUser,
  assignees: initialAssignees,
  readonly,
  maxAssignees = 10,
  onAssignmentChange,
  onCopilotAgenticAssignment,
  assignableToCopilot = false,
  copilotAssignmentModal,
  useAgenticAutofix = false,
  showAssignToAgentButton = false,
  assignToAgentAssignee,
  onAssignError = defaultOnAssignError,
}: AssigneesSectionProps<Response>) {
  const [assignees, setAssignees] = useState<Assignee[]>(initialAssignees)
  const [showCopilotAssignmentMessage, setShowCopilotAssignmentMessage] = useState(false)
  const [copilotAssignmentModalOpen, setCopilotAssignmentModalOpen] = useState(false)
  const [isSelectingAgent, setIsSelectingAgent] = useState(false)
  const [pickerInstanceKey, setPickerInstanceKey] = useState(0)
  const needsReloadOnModalCloseRef = useRef(false)
  const {mutate: mutateUpdateAssignees, isPending: mutationPending} = useUpdateAlertAssigneesMutation<Response>(
    updateAssigneesPath,
    {
      onError: onAssignError,
    },
  )

  const assignToAgentButtonRef = useRef<HTMLButtonElement>(null)

  const handleOpenCopilotAssignmentModal = useCallback(() => {
    setCopilotAssignmentModalOpen(true)
    setPickerInstanceKey(prev => prev + 1)
  }, [])

  const handleSelectionChange = useCallback(
    (selectedAssignees: Assignee[]) => {
      const hasCopilot = selectedAssignees.some(a => a.isCopilot)
      const wasCopilotPreviously = assignees.some(a => a.isCopilot)

      if (copilotAssignmentModal) {
        const willOpenModal = hasCopilot && !wasCopilotPreviously

        // When Copilot is newly selected, strip it from the PATCH — the modal
        // handles the Copilot assignment via a separate endpoint. Otherwise,
        // send all selectedAssignees so the PATCH preserves existing Copilot.
        const assigneesForPatch = willOpenModal ? selectedAssignees.filter(a => !a.isCopilot) : selectedAssignees
        const currentAssigneesToCompare = willOpenModal ? assignees.filter(a => !a.isCopilot) : assignees
        const assigneesChanged =
          assigneesForPatch.length !== currentAssigneesToCompare.length ||
          assigneesForPatch.some(a => !currentAssigneesToCompare.find(c => c.id === a.id))

        if (!assigneesChanged && !willOpenModal) return

        if (assigneesChanged) {
          mutateUpdateAssignees(
            {assigneeIds: assigneesForPatch.map(a => a.id)},
            {
              onSuccess: data => {
                setAssignees(data ? data.assignees : assigneesForPatch)
                if (willOpenModal) {
                  needsReloadOnModalCloseRef.current = true
                  handleOpenCopilotAssignmentModal()
                } else {
                  onAssignmentChange?.()
                }
              },
            },
          )
        } else {
          handleOpenCopilotAssignmentModal()
        }
        return
      }

      setIsSelectingAgent(hasCopilot && !wasCopilotPreviously)

      // Existing single-endpoint flow (code scanning, etc.)
      mutateUpdateAssignees(
        {assigneeIds: selectedAssignees.map(a => a.id)},
        {
          onSuccess: data => {
            setAssignees(data ? data.assignees : selectedAssignees)
            const isCopilotAssignmentNew = data?.isCopilotAssignmentNew ?? false
            if (isCopilotAssignmentNew && useAgenticAutofix) {
              displayFlashMessage(
                'Successfully assigned to Copilot to generate a fix. Copilot will open a pull request.',
              )
              onCopilotAgenticAssignment?.(data)
            } else {
              setShowCopilotAssignmentMessage(isCopilotAssignmentNew)
            }
            onAssignmentChange?.()
          },
        },
      )
    },
    [
      copilotAssignmentModal,
      assignees,
      mutateUpdateAssignees,
      onAssignmentChange,
      handleOpenCopilotAssignmentModal,
      useAgenticAutofix,
      onCopilotAgenticAssignment,
    ],
  )

  const handleDirectAssignToAgent = () => {
    if (!assignToAgentAssignee) {
      return
    }

    handleSelectionChange([...assignees, assignToAgentAssignee])
  }

  return (
    <AlertMetadata>
      {showCopilotAssignmentMessage && (
        <InlineMessage variant="success" size="small" className="pb-2">
          Successfully assigned to Copilot to apply the autofix for this alert. Copilot will open a PR.
        </InlineMessage>
      )}
      {readonly ? (
        <AlertMetadataHeader title="Assignees" />
      ) : (
        <AssigneePicker
          key={`assignee-picker-${pickerInstanceKey}`}
          path={availableAssigneesPath}
          assignableToCopilot={assignableToCopilot}
          anchorElement={(props: React.HTMLAttributes<HTMLElement>, ref: RefObject<HTMLButtonElement | null>) => (
            <AlertMetadataHeader title="Assignees" buttonProps={props} buttonRef={ref} />
          )}
          initialSelectedAssignees={assignees}
          currentUser={currentUser}
          maximumAssignees={maxAssignees}
          onSelectionChange={handleSelectionChange}
          shortcutsEnabled={false}
          title={`Assign up to ${maxAssignees} people to this alert`}
          loading={mutationPending}
        />
      )}

      <AlertMetadataContent>
        {assignees.length > 0 ? (
          <AssigneesList assignees={assignees} />
        ) : (
          <span>
            {readonly ? (
              <>No one assigned</>
            ) : (
              <>
                No one -{' '}
                <Button
                  loading={mutationPending}
                  variant="link"
                  onClick={() =>
                    mutateUpdateAssignees(
                      {assigneeIds: [currentUser.id]},
                      {
                        onSuccess: () => {
                          setAssignees([currentUser])
                          onAssignmentChange?.()
                        },
                      },
                    )
                  }
                >
                  Assign yourself
                </Button>
              </>
            )}
          </span>
        )}
        {showAssignToAgentButton && assignableToCopilot && !readonly && !assignees.some(a => a.isCopilot) && (
          <div className="tmp-mt-2">
            {copilotAssignmentModal && (
              <Suspense fallback={null}>
                <LazyCopilotAssignmentButton ref={assignToAgentButtonRef} onClick={handleOpenCopilotAssignmentModal} />
              </Suspense>
            )}
            {!copilotAssignmentModal && assignToAgentAssignee && (
              <Button
                leadingVisual={AgentIcon}
                size="small"
                block
                loading={mutationPending && isSelectingAgent}
                inactive={mutationPending && !isSelectingAgent}
                onClick={handleDirectAssignToAgent}
              >
                Assign to Copilot
              </Button>
            )}
          </div>
        )}
        {copilotAssignmentModal && (
          <Suspense fallback={null}>
            <LazyCopilotAssignmentModal
              isOpen={copilotAssignmentModalOpen}
              onClose={() => {
                setCopilotAssignmentModalOpen(false)
                if (needsReloadOnModalCloseRef.current) {
                  needsReloadOnModalCloseRef.current = false
                  onAssignmentChange?.()
                }
              }}
              repository={copilotAssignmentModal.repository}
              issueNumbers={copilotAssignmentModal.alertNumbers}
              onAssignmentComplete={() => {
                needsReloadOnModalCloseRef.current = false
                copilotAssignmentModal.onAssignmentComplete?.()
              }}
              onSubmit={copilotAssignmentModal.onSubmit}
              title={copilotAssignmentModal.title}
              description={copilotAssignmentModal.description}
              returnFocusRef={assignToAgentButtonRef}
            />
          </Suspense>
        )}
      </AlertMetadataContent>
    </AlertMetadata>
  )
}
