import {testIdProps} from '@github-ui/test-id-props'
import {GearIcon, InfoIcon} from '@primer/octicons-react'
import {AnchoredOverlay, Button, Heading} from '@primer/react'
import {clsx} from 'clsx'
import {useState} from 'react'

import styles from './AlertMetadataHeader.module.css'
import type {AlertMetadataHeaderProps} from './types'

function InfoButton({title, infoContent}: {title: string; infoContent: React.ReactNode}) {
  const [open, setOpen] = useState(false)

  return (
    <AnchoredOverlay
      open={open}
      onOpen={() => setOpen(true)}
      onClose={() => setOpen(false)}
      align="end"
      side="outside-top"
      overlayProps={{maxWidth: 'medium'}}
      renderAnchor={anchorProps => (
        <Button {...anchorProps} block variant="invisible" trailingAction={InfoIcon}>
          <span className="sr-only">About {title}</span>
        </Button>
      )}
    >
      {infoContent}
    </AnchoredOverlay>
  )
}

const EditButton = ({
  title,
  buttonRef,
  buttonProps,
}: {
  title: string
  buttonRef?: React.Ref<HTMLButtonElement>
  buttonProps: React.ButtonHTMLAttributes<HTMLButtonElement>
}) => (
  <Button block variant="invisible" trailingAction={GearIcon} ref={buttonRef} {...buttonProps}>
    <span className="sr-only">{`Edit ${title}`}</span>
  </Button>
)

export const AlertMetadataHeader = ({headingTag = 'h3', title, testId, ...rest}: AlertMetadataHeaderProps) => (
  <div className={styles.AlertMetadataHeader} {...(testId ? testIdProps(testId) : {})}>
    <Heading as={headingTag} className={clsx(styles.AlertMetadataHeading, 'f6 color-fg-muted')}>
      {title}
    </Heading>

    {rest.variant === 'info' ? (
      <InfoButton title={title} infoContent={rest.infoContent} />
    ) : (
      rest.buttonProps && <EditButton title={title} buttonRef={rest.buttonRef} buttonProps={rest.buttonProps} />
    )}
  </div>
)
